CREATE TABLE IF NOT EXISTS m_client_kyc_verification ( id BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY, client_id BIGINT NOT NULL, session_id VARCHAR(255) NOT NULL, workflow_id VARCHAR(255) NOT NULL, workflow_version INTEGER, webhook_type VARCHAR(100), kyc_status VARCHAR(50) NOT NULL, kyc_timestamp BIGINT, kyc_created_at BIGINT, metadata_text TEXT, created_by BIGINT NOT NULL, created_on_utc TIMESTAMP WITH TIME ZONE NOT NULL, last_modified_by BIGINT NOT NULL, last_modified_on_utc TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT pk_m_client_kyc_verification PRIMARY KEY (id), CONSTRAINT fk_kyc_verification_client FOREIGN KEY (client_id) REFERENCES m_client(id) ON UPDATE RESTRICT ON DELETE RESTRICT, CONSTRAINT fk_kyc_verification_created_by FOREIGN KEY (created_by) REFERENCES m_appuser(id) ON UPDATE RESTRICT ON DELETE RESTRICT, CONSTRAINT fk_kyc_verification_last_modified_by FOREIGN KEY (last_modified_by) REFERENCES m_appuser(id) ON UPDATE RESTRICT ON DELETE RESTRICT );
CREATE UNIQUE INDEX uk_kyc_verification_session ON m_client_kyc_verification(session_id);
CREATE INDEX idx_kyc_verification_client ON m_client_kyc_verification(client_id);
CREATE INDEX idx_kyc_verification_status ON m_client_kyc_verification(kyc_status);
